from pathlib import Path
import json


def read(path):
    return Path(path).read_text(encoding="utf-8")


def write(path, text):
    Path(path).write_text(text, encoding="utf-8")


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly 1 occurrence, found {count}")
    return text.replace(old, new, 1)


# 1) Make the i18n core deterministic: completion layer first, then navigation,
# and do not let init return while the presentation layer is still racing in.
core_path = "assets/i18n/core-v2.js"
core = read(core_path)
core = replace_once(
    core,
    '''        await loadUiScript("theme-manager.js?v=20260908-4", "BetInsightTheme");
        await loadUiScript("navigation-enhancements.js?v=20260909-3", "BetInsightNavigationEnhancements");
        await loadUiScript("i18n/member-completion.js?v=20260912-1", "BetInsightMemberCompletion");
        return true;''',
    '''        await loadUiScript("theme-manager.js?v=20260908-4", "BetInsightTheme");
        await loadUiScript("i18n/member-completion.js?v=20260913-1", "BetInsightMemberCompletion");
        await loadUiScript("navigation-enhancements.js?v=20260913-1", "BetInsightNavigationEnhancements");
        return true;''',
    "core enhancement order",
)
core = replace_once(
    core,
    '''        loadUiEnhancements();
        return language;''',
    '''        await loadUiEnhancements();
        return language;''',
    "core init await enhancements",
)
core = replace_once(
    core,
    '''        loadUiEnhancements();
        return defaultLanguage;''',
    '''        await loadUiEnhancements();
        return defaultLanguage;''',
    "core fallback await enhancements",
)
write(core_path, core)


# 2) Remove the observer storm in the member-wide completion layer.
# MutationObserver callbacks are asynchronous, so the previous `applying` flag alone
# did not suppress the mutation records generated by the translation pass itself.
completion_path = "assets/i18n/member-completion.js"
completion = read(completion_path)
completion = replace_once(
    completion,
    '''    } finally { applying=false; }
  }

  function startObserver() {''',
    '''    } finally {
      if (observer) observer.takeRecords();
      applying=false;
    }
  }

  function startObserver() {''',
    "member completion clear own walk records",
)
completion = replace_once(
    completion,
    '''    observer=new MutationObserver(records=>{
      if (applying) return;
      for (const record of records) {
        if (record.type === "characterData") processText(record.target);
        else if (record.type === "attributes") processAttr(record.target,record.attributeName);
        else record.addedNodes.forEach(node=>{
          if (node.nodeType === Node.TEXT_NODE) processText(node);
          else if (node.nodeType === Node.ELEMENT_NODE) walk(node);
        });
      }
    });''',
    '''    observer=new MutationObserver(records=>{
      if (applying) return;
      applying=true;
      try {
        for (const record of records) {
          if (record.type === "characterData") processText(record.target);
          else if (record.type === "attributes") processAttr(record.target,record.attributeName);
          else record.addedNodes.forEach(node=>{
            if (node.nodeType === Node.TEXT_NODE) processText(node);
            else if (node.nodeType === Node.ELEMENT_NODE) walk(node);
          });
        }
      } finally {
        observer.takeRecords();
        applying=false;
      }
    });''',
    "member completion guarded observer",
)
write(completion_path, completion)


# 3) The legacy dashboard adapter remains for safe routing and locale formatters,
# but it must not run a second full-DOM translator/observer when the new completion
# layer is present. This removes the second source of feedback loops.
dashboard_path = "assets/i18n/dashboard-legacy.js"
dashboard = read(dashboard_path)
dashboard = replace_once(
    dashboard,
    '''  function applyPseudoLabels() {
    let style = document.getElementById("bi-dashboard-language-style");
    if (!style) { style = document.createElement("style"); style.id = "bi-dashboard-language-style"; document.head.appendChild(style); }
    style.textContent = lang() === "en" ? `.private-row-hidden::after{content:"${t("privacyEmail",{},"Email protected")}"!important}.private-token-hidden::after{content:"${t("privacyAccess",{},"Personal access protected")}"!important}.private-value-hidden::after{content:"${t("privacyProtected",{},"Protected")}"!important}.membership-info-tier.current-tier::after{content:"${t("yourPlan",{},"YOUR PLAN")}"!important}` : "";
  }''',
    '''  function applyPseudoLabels() {
    let style = document.getElementById("bi-dashboard-language-style");
    if (!style) { style = document.createElement("style"); style.id = "bi-dashboard-language-style"; document.head.appendChild(style); }
    style.textContent = lang() !== "de" ? `.private-row-hidden::after{content:"${t("privacyEmail",{},"Protected")}"!important}.private-token-hidden::after{content:"${t("privacyAccess",{},"Protected")}"!important}.private-value-hidden::after{content:"${t("privacyProtected",{},"Protected")}"!important}.membership-info-tier.current-tier::after{content:"${t("yourPlan",{},"YOUR PLAN")}"!important}` : "";
  }''',
    "dashboard pseudo labels all languages",
)
dashboard = replace_once(
    dashboard,
    '''  async function boot() {
    installSafeRouting();
    await i18n()?.init?.();
    walk(document.body);
    const observer = new MutationObserver(records => {
      if (applying) return;
      for (const record of records) {
        if (record.type === "characterData") processText(record.target);
        else for (const node of record.addedNodes) node.nodeType===Node.TEXT_NODE ? processText(node) : (node instanceof Element && walk(node));
      }
    });
    observer.observe(document.body,{subtree:true,childList:true,characterData:true});
    window.addEventListener("bi:languagechange",()=>walk(document.body));
  }''',
    '''  async function boot() {
    installSafeRouting();
    await i18n()?.init?.();

    const refreshLocaleOnly = () => {
      applyLocaleFunctions();
      applyPseudoLabels();
      document.title = t("title", {}, "BetInsight Profil & Empfehlungscenter");
    };

    // The six-language member completion layer is now the single DOM translator.
    // Keep this legacy adapter for safe routing and number/date formatting only.
    if (window.BetInsightMemberCompletion) {
      refreshLocaleOnly();
      window.addEventListener("bi:languagechange", refreshLocaleOnly);
      return;
    }

    // Fallback for an unlikely completion-layer load failure.
    walk(document.body);
    const observer = new MutationObserver(records => {
      if (applying) return;
      for (const record of records) {
        if (record.type === "characterData") processText(record.target);
        else for (const node of record.addedNodes) node.nodeType===Node.TEXT_NODE ? processText(node) : (node instanceof Element && walk(node));
      }
    });
    observer.observe(document.body,{subtree:true,childList:true,characterData:true});
    window.addEventListener("bi:languagechange",()=>walk(document.body));
  }''',
    "dashboard single translator mode",
)
write(dashboard_path, dashboard)


