app_nav = replace_once(
    app_nav,
    'await loadScript("i18n/core-v2.js","BetInsightI18n");',
    'await loadScript("i18n/core-v2.js?v=20260913-1","BetInsightI18n");',
    "app navigation core cache bust",
)
app_nav = replace_once(
    app_nav,
    '        await loadScript("i18n/dashboard-completion.js");',
    '        if (!window.BetInsightMemberCompletion) await loadScript("i18n/dashboard-completion.js");',
    "app navigation skip redundant dashboard completion",
)
write(app_nav_path, app_nav)


# 5) Navigation enhancement labels must update in all six languages instead of
# becoming permanently German after the first render.
